<script setup lang="ts">
import { computed, inject, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import Button from 'primevue/button'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import InputText from 'primevue/inputtext'; import Message from 'primevue/message'; import Select from 'primevue/select'; import Tag from 'primevue/tag';
import { getIssues, issuePriorities, issueStatuses, issueTypes } from '../../api/issues';
import type { IssueInfo } from '../../api/types';
import IssueCreateDialog from '../../features/issues/IssueCreateDialog.vue';
import { projectWorkspaceKey } from '../../features/projects/projectContext';

const context=inject(projectWorkspaceKey)!;const route=useRoute();const router=useRouter();
const issues=ref<IssueInfo[]>([]);const total=ref(0);const loading=ref(false);const error=ref('');const createVisible=ref(false);
const search=ref('');const type=ref<string|null>(null);const status=ref<string|null>(null);const priority=ref<string|null>(null);const assignee=ref<string|null>(null);const page=ref(1);const pageSize=ref(20);
const canCreate=computed(()=>context.project.value.status==='Active'&&context.project.value.currentUserRole!=='Viewer');
const assigneeOptions=computed(()=>context.members.value.map(item=>({label:item.email,value:item.userId})));
function fromQuery(){search.value=String(route.query.search??'');type.value=route.query.type?String(route.query.type):null;status.value=route.query.status?String(route.query.status):null;priority.value=route.query.priority?String(route.query.priority):null;assignee.value=route.query.assigneeUserId?String(route.query.assigneeUserId):null;page.value=Math.max(1,Number(route.query.page)||1);pageSize.value=[10,20,50,100].includes(Number(route.query.pageSize))?Number(route.query.pageSize):20;}
async function load(){loading.value=true;error.value='';try{const result=await getIssues(context.project.value.id,{search:search.value.trim(),type:type.value,status:status.value,priority:priority.value,assigneeUserId:assignee.value,page:page.value,pageSize:pageSize.value});issues.value=result?.items??[];total.value=result?.totalCount??0;}catch(cause){error.value=cause instanceof Error?cause.message:'Unable to load Issues.';}finally{loading.value=false;}}
async function apply(){page.value=1;await router.push({name:'project-issues',query:query()});}
function query(){return Object.fromEntries(Object.entries({search:search.value.trim()||undefined,type:type.value||undefined,status:status.value||undefined,priority:priority.value||undefined,assigneeUserId:assignee.value||undefined,page:page.value===1?undefined:String(page.value),pageSize:pageSize.value===20?undefined:String(pageSize.value)}).filter(([,value])=>value!==undefined));}
function changePage(event:{page:number;rows:number}){page.value=event.page+1;pageSize.value=event.rows;void router.push({name:'project-issues',query:query()});}
function openIssue(issue:IssueInfo){void router.push({name:'project-issue-detail',params:{projectId:context.project.value.id,issueId:issue.id},query:{from:route.fullPath}});}
function created(issue:IssueInfo){void openIssue(issue);}
watch(()=>route.query,()=>{fromQuery();void load();},{immediate:true,deep:true});
</script>
<template><section class="workspace-panel"><header class="section-header"><div><h2>Issues</h2><p>Track features, bugs and change requests.</p></div><Button v-if="canCreate" label="Create Issue" icon="pi pi-plus" @click="createVisible=true" /></header><Message v-if="error" severity="error">{{error}}</Message><div class="issue-filters"><InputText v-model="search" placeholder="Search title or description" aria-label="Search Issues" @keyup.enter="apply"/><Select v-model="type" :options="issueTypes" show-clear placeholder="Type"/><Select v-model="status" :options="issueStatuses" show-clear placeholder="Status"/><Select v-model="priority" :options="issuePriorities" show-clear placeholder="Priority"/><Select v-model="assignee" :options="assigneeOptions" option-label="label" option-value="value" show-clear placeholder="Assignee"/><Button label="Apply" severity="secondary" @click="apply"/></div><DataTable :value="issues" :loading="loading" data-key="id" lazy paginator :rows="pageSize" :first="(page-1)*pageSize" :total-records="total" :rows-per-page-options="[10,20,50,100]" @page="changePage" @row-click="openIssue($event.data)"><template #empty>No matching Issues.</template><Column field="title" header="Title"/><Column field="type" header="Type"/><Column field="priority" header="Priority"/><Column header="Status"><template #body="{data}"><Tag :value="data.status"/></template></Column><Column field="assigneeEmail" header="Assignee"><template #body="{data}">{{data.assigneeEmail||'Unassigned'}}</template></Column><Column header="Actions"><template #body="{data}"><Button label="Open" size="small" severity="secondary" @click.stop="openIssue(data)"/></template></Column></DataTable><IssueCreateDialog v-model:visible="createVisible" @created="created"/></section></template>
<style scoped>.section-header{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.section-header h2,.section-header p{margin:.2rem 0}.issue-filters{display:grid;grid-template-columns:minmax(12rem,2fr) repeat(4,minmax(8rem,1fr)) auto;gap:.6rem;margin:1rem 0}@media(max-width:850px){.issue-filters{grid-template-columns:1fr}}</style>
